<script>

  import { onMount } from 'svelte';



  let search = $state('');

  let direction = $state('All');

  let menuOpen = $state(false);



  const products = [

    { name: 'Ethiopian Coffee', category: 'Agriculture', direction: 'Export', origin: 'Ethiopia', description: 'Green coffee sourcing for international buyers.', photo: 'https://images.unsplash.com/photo-1447933601403-0c6688de566e?w=1000&q=80' },

    { name: 'Sesame Seeds', category: 'Oilseeds', direction: 'Export', origin: 'Ethiopia', description: 'Bulk sesame sourcing from Ethiopian suppliers.', photo: 'https://images.unsplash.com/photo-1509440159596-0249088772ff?w=1000&q=80' },

    { name: 'Kidney Beans', category: 'Pulses', direction: 'Export', origin: 'Ethiopia', description: 'Pulses available for buyer inquiries.', photo: 'https://images.unsplash.com/photo-1515543904379-3d757afe72e4?w=1000&q=80' },

    { name: 'Agricultural Machinery', category: 'Equipment', direction: 'Import', origin: 'International', description: 'Connect with suppliers of farming equipment.', photo: 'https://images.unsplash.com/photo-1530267981375-f0de937f5f13?w=1000&q=80' },

    { name: 'Industrial Equipment', category: 'Equipment', direction: 'Import', origin: 'International', description: 'Find equipment for Ethiopian businesses.', photo: 'https://images.unsplash.com/photo-1581092160607-ee22621dd758?w=1000&q=80' },

    { name: 'Ethiopian Spices', category: 'Agriculture', direction: 'Export', origin: 'Ethiopia', description: 'Explore Ethiopian spice sourcing opportunities.', photo: 'https://images.unsplash.com/photo-1596040033229-a9821ebd058d?w=1000&q=80' }

  ];



  let filteredProducts = $derived(products.filter((product) => {

    const query = search.trim().toLowerCase();

    return (direction === 'All' || product.direction === direction) &&

      (!query || `${product.name} ${product.category} ${product.direction} ${product.origin} ${product.description}`.toLowerCase().includes(query));

  }));



  const services = [

    { number: '01', symbol: '↗', title: 'Export discovery', description: 'Showcase Ethiopian products and help international buyers explore sourcing opportunities.', href: '/export', link: 'Explore exports' },

    { number: '02', symbol: '↙', title: 'Import sourcing', description: 'Help Ethiopian businesses discover international machinery, equipment and supplies.', href: '/import', link: 'Explore imports' },

    { number: '03', symbol: '◎', title: 'Buyer–supplier connections', description: 'Make product inquiries and begin conversations with potential trading partners.', href: '/contact', link: 'Send an inquiry' },

    { number: '04', symbol: '✓', title: 'Supplier submissions', description: 'Submit product information for administrative review before publication.', href: '/sell', link: 'Submit a product' }

  ];



  onMount(() => {

    if (!('IntersectionObserver' in window)) return;

    const observer = new IntersectionObserver((entries) => {

      for (const entry of entries) {

        if (entry.isIntersecting) {

          entry.target.classList.add('is-visible');

          observer.unobserve(entry.target);

        }

      }

    }, { threshold: 0.08 });

    document.querySelectorAll('[data-reveal]').forEach((el) => observer.observe(el));

    return () => observer.disconnect();

  });

</script>



